select upper(name) as a, lower(name) as b, concat(name, '!') as c, concat_ws(',', name, body) as d, trim(name) as e, substring(name, 1, 2) as f, left(name, 1) as g, replace(name, 'a', 'b') as h, reverse(name) as i, repeat(name, 2) as j, lpad(name, 5, ' ') as k, length(name) as l, char_length(name) as m, hex(name) as o, sha2(name, 256) as r, to_base64(name) as s, quote(name) as u, space(n) as v, insert(name, 1, 1, 'x') as w, elt(n, 'a', 'b') as x, field(name, 'a', 'b') as z from t where n between -1 and 2
